private int findSlot(int h, K k) {
    int available = -1;
    int j = h;
    int probe = 0;
    do {
        probe++;
        probes++;
        if (isAvailable(j)) {
            if (available == -1) {
                available = j;
            }
            if (table[j] == null) {
                break;
            }
        } else if (table[j].getKey().equals(k)) {
            recordProbe(probe);
            return j;
        } else if (probe == 1) {
            collisions++;
        }
        j = (j + 1) % capacity;
    } while (j != h);
    recordProbe(probe);
    if (available < 0) {
        return -1;
    }
    return -(available + 1);
}

